H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -6, yMax: 6 });
v.grid(); v.axes();
const Q = P.Q, d = Math.max(0.5, P.d);
const k = 9e9, mu = 1e-6;
// A source charge at the origin. We draw the field-vector grid (E points away
// from + and toward −) and a roving test point at distance d sampling E.
const x0 = 0, y0 = 0;
const col = Q > 0 ? H.colors.warn : H.colors.accent;
v.circle(x0, y0, 11, { fill: col, stroke: H.colors.bg, width: 2 });
v.text(Q > 0 ? "+" : "−", x0 - 0.18, y0 + 0.3, { color: H.colors.ink, size: 18, weight: 700 });
// field arrows on a coarse grid, length ~ 1/r (clamped) so the inverse-square falloff reads
for (let gx = -8; gx <= 8; gx += 2) {
  for (let gy = -4; gy <= 4; gy += 2) {
    const rx = gx - x0, ry = gy - y0, r = Math.hypot(rx, ry);
    if (r < 1.2) continue;
    const dir = Q > 0 ? 1 : -1; // outward for +, inward for −
    const ux = dir * rx / r, uy = dir * ry / r;
    const L = Math.min(1.6, 6 / (r * r)); // visual length falls off like 1/r^2
    v.arrow(gx, gy, gx + ux * (0.5 + L), gy + uy * (0.5 + L), { color: H.colors.violet, width: 1.6 });
  }
}
// roving test charge orbiting at radius d; E = k|Q|/r^2 measured there
const ang = t * 0.8;
const tx = x0 + d * Math.cos(ang), ty = y0 + d * Math.sin(ang);
const E = k * Math.abs(Q) * mu / (d * d);
const dir = Q > 0 ? 1 : -1;
const ux = dir * Math.cos(ang), uy = dir * Math.sin(ang);
v.dot(tx, ty, { r: 6, fill: H.colors.good });
v.arrow(tx, ty, tx + ux * 1.6, ty + uy * 1.6, { color: H.colors.good, width: 3 });
H.text("Electric field:  E = k Q / r²   (force per unit charge)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("|E| at r = " + d.toFixed(1) + " m  =  " + E.toExponential(2) + " N/C", 24, 52, { color: H.colors.good, size: 13 });
H.text("Q = " + Q.toFixed(1) + " µC   —  arrows point away from +, toward −; longer = stronger field", 24, 72, { color: H.colors.sub, size: 12 });
